                        seen.add((ny, nx))
                        stack.append((ny, nx))
            comps.append((color, cells))

    # The singleton colored pixel gives the paint color. Find a component
    # whose shape exactly matches another component of that color.
    singleton_color = next((color for color, cells in comps if len(cells) == 1), None)
    if singleton_color is None:
        return out

    def shape(cells):
        y0 = min(y for y, x in cells)
        x0 = min(x for y, x in cells)
        return frozenset((y-y0, x-x0) for y, x in cells)

